sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var currentSysId = g_form.getUniqueValue();

    var ga = new GlideAjax('BranchUtils');
    ga.addParam('sysparm_name', 'checkManagerExists');
    ga.addParam('sysparm_manager', newValue);
    ga.addParam('sysparm_current', currentSysId);

    ga.getXMLAnswer(function(response) {
        var exists = response === 'true';
        if (exists) {
            alert('This manager is already assigned to another branch.');
            g_form.clearValue('branch_manager');
        }
    });
}
